import sympy

# Top-level setup
# We evaluate the witness in the ring of integers Z, which is a commutative ring.
# Ideals in Z are generated by a single integer, so we represent them simply as integers.
Z = sympy.S.Integers

def parse_witness(witness):
    """
    Extracts I, Q_list, and Q_prime_list from the witness.
    The witness can be a dictionary, a tuple (R, I, Q_list, Q_prime_list), 
    or a tuple (I, Q_list, Q_prime_list).
    """
    if isinstance(witness, dict):
        I = witness.get('I')
        Q_list = witness.get('Q_list', [])
        Q_prime_list = witness.get('Q_prime_list', [])
        return I, Q_list, Q_prime_list
    elif isinstance(witness, (list, tuple)):
        if len(witness) == 4:
            return witness[1], witness[2], witness[3]
        elif len(witness) == 3:
            return witness[0], witness[1], witness[2]
    elif hasattr(witness, 'I') and hasattr(witness, 'Q_prime_list'):
        I = witness.I
        Q_list = getattr(witness, 'Q_list', [])
        Q_prime_list = witness.Q_prime_list
        return I, Q_list, Q_prime_list
    raise ValueError("Invalid witness format")

def is_primary(q):
    """Checks if the ideal generated by q is primary in Z."""
    try:
        q = abs(int(q))
    except Exception:
        return False
    if q == 1:
        return False
    if q == 0:
        return True
    factors = sympy.factorint(q)
    return len(factors) == 1

def radical(q):
    """Returns the generator of the radical of the ideal generated by q in Z."""
    q = abs(int(q))
    if q == 0:
        return 0
    if q == 1:
        return 1
    factors = sympy.factorint(q)
    res = 1
    for p in factors:
        res *= p
    return res

def intersection(ideals):
    """Returns the generator of the intersection of a list of ideals in Z."""
    if not ideals:
        return 1
    res = abs(int(ideals[0]))
    for q in ideals[1:]:
        res = sympy.lcm(res, abs(int(q)))
    return res

def is_minimal_primary_decomposition(I, Q_prime_list):
    """Checks if Q_prime_list is a minimal primary decomposition of I in Z."""
    if not isinstance(Q_prime_list, (list, tuple)):
        return False
    if not all(is_primary(q) for q in Q_prime_list):
        return False
    if abs(int(I)) != intersection(Q_prime_list):
        return False
    
    # Check that the associated prime ideals (radicals) are distinct
    rads = [radical(q) for q in Q_prime_list]
    if len(rads) != len(set(rads)):
        return False
        
    # Check irredundancy (no ideal can be omitted)
    for i in range(len(Q_prime_list)):
        others = Q_prime_list[:i] + Q_prime_list[i+1:]
        if intersection(others) == abs(int(I)):
            return False
            
    return True

def conditions(witness) -> list[bool]:
    try:
        I, Q_list, Q_prime_list = parse_witness(witness)
        I = int(I)
        Q_list = [int(q) for q in Q_list]
        Q_prime_list = [int(q) for q in Q_prime_list]
    except Exception:
        return [False, False, False, False]

    # H_1: R is a commutative ring
    # Since we successfully parsed the witness into integers, we are operating in Z, 
    # which is inherently a commutative ring.
    h1 = True

    # H_2: I is a proper ideal of R
    try:
        h2 = abs(I) != 1
    except Exception:
        h2 = False

    # H_3: I = \bigcap_{j=1}^m Q'_j is a minimal primary decomposition of I
    try:
        h3 = is_minimal_primary_decomposition(I, Q_prime_list)
    except Exception:
        h3 = False

    # ¬Q: n != m or the sets of prime ideals are not identical
    try:
        if len(Q_list) != len(Q_prime_list):
            neg_q = True
        else:
            rads_Q = set(radical(q) for q in Q_list)
            rads_Q_prime = set(radical(q) for q in Q_prime_list)
            neg_q = (rads_Q != rads_Q_prime)
    except Exception:
        neg_q = False

    return [h1, h2, h3, neg_q]

CONDITION_LABELS = [
    "H_1: R is a commutative ring",
    "H_2: I is a proper ideal of R",
    "H_3: I = \\bigcap_{j=1}^m Q'_j is a minimal primary decomposition of I",
    "¬Q: n != m or the sets of prime ideals are not identical"
]

